#include <stdio.h>

void f(char* str1, char* str2) {
    int i, j;
    for(i=0, j=0 ; str1[i] != 0 ; i++) {
        if(str1[i] != str1[i+1]) {
            str2[j] = str1[i];
            j++;
        }
    }
    str2[j] = 0;
}

int main()
{
    char a[20] = "aaabbccccdeffff", b[20];
    f(a, b);
    printf("%s\n", b);
    return 0;
}

