#include <stdio.h>
#include <string.h>

int cnt[26];
char str1[101], str2[101];

int main()
{
    int i;
    scanf("%s %s", str1, str2);
    for (i = 0; str1[i] != '\0'; i++)
        cnt[str1[i] - 'a'] += 1;
    for (i = 0; str2[i] != '\0'; i++)
        cnt[str2[i] - 'a'] -= 1;
    for (i = 0; i < 26; i++) {
        if (cnt[i]) {
            printf("%s %d", str1, i);
            break;
        }
    }
    if (i == 26)
        printf("%s %d", str2, i);
    return 0;
}
